421	// run executes a subcommand on the external binary and returns stdout bytes.
422	// If stdin is non-nil it is piped to the process. On non-zero exit, stderr is
423	// included in the returned error.
424	func (e *Agent) run(ctx context.Context, stdin []byte, args ...string) ([]byte, error) {
425		// Apply a default timeout when the caller hasn't set a deadline, so a hung
426		// external binary can't block the CLI (or git hooks) indefinitely.
427		if _, ok := ctx.Deadline(); !ok {
428			var cancel context.CancelFunc
429			ctx, cancel = context.WithTimeout(ctx, defaultRunTimeout)
430			defer cancel()
431		}
432		cmd := exec.CommandContext(ctx, e.binaryPath, args...)
433		// Ensure I/O goroutines are released shortly after the process is killed,
434		// so cmd.Run() doesn't block waiting for pipe reads.
435		cmd.WaitDelay = 3 * time.Second
436	
437		// Set environment: repo root + protocol version
438		cmd.Env = append(cmd.Environ(),
439			"ENTIRE_PROTOCOL_VERSION="+strconv.Itoa(ProtocolVersion),
440		)
441		if repoRoot, err := paths.WorktreeRoot(ctx); err == nil {
442			cmd.Env = append(cmd.Env, "ENTIRE_REPO_ROOT="+repoRoot)
443			cmd.Dir = repoRoot
444		}
445	
446		if stdin != nil {
447			cmd.Stdin = bytes.NewReader(stdin)
448		}
449	
450		const maxOutputBytes = 10 * 1024 * 1024 // 10 MB
451	
452		var stdoutBuf, stderrBuf bytes.Buffer
453		stdoutLW := &limitedWriter{buf: &stdoutBuf, limit: maxOutputBytes}
454		stderrLW := &limitedWriter{buf: &stderrBuf, limit: maxOutputBytes}
455		cmd.Stdout = stdoutLW
456		cmd.Stderr = stderrLW
457	
458		if err := cmd.Run(); err != nil {
459			errMsg := strings.TrimSpace(stderrBuf.String())
460			if errMsg != "" {
461				return nil, fmt.Errorf("%s: %s", args[0], errMsg)
462			}
463			return nil, fmt.Errorf("%s: %w", args[0], err)
464		}
465	
466		if stdoutLW.truncated {
467			return nil, fmt.Errorf("%s: output exceeded %d byte limit", args[0], maxOutputBytes)
468		}
