func TestRun_PropagatesCLIVersionEnv(t *testing.T) {
	t.Parallel()

	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	// The mock binary echoes ENTIRE_CLI_VERSION back as the subcommand output
	// so the test can assert the env var reached the spawned process.
	script := `#!/bin/sh
case "$1" in
  info)
    echo '` + validInfoJSON + `'
    ;;
  echo-cli-version)
    printf '%s' "$ENTIRE_CLI_VERSION"
    ;;
esac
`
	binPath := testBinaryDir(t, script)
	ea := newExternalAgent(t, binPath)

	out, err := ea.run(context.Background(), nil, "echo-cli-version")
	if err != nil {
		t.Fatalf("run: %v", err)
	}
	if got := string(out); got != versioninfo.Version {
		t.Errorf("ENTIRE_CLI_VERSION in spawned process = %q, want %q", got, versioninfo.Version)
	}
}

